351	            //OverloadComparisonResult ocr = this;
352	
353	            List<FType> pl1 = o1.getParams();
354	            List<FType> pl2 = o2.getParams();
355	
356	            {
357	                l1 = pl1.size();
358	                l2 = pl2.size();
359	
360	                rest1 = (l1 > 0 && pl1.get(l1 - 1) instanceof FTypeRest);
361	                rest2 = (l2 > 0 && pl2.get(l2 - 1) instanceof FTypeRest);
362	
363	                // by construction, l1 is bigger.
364	                // (see sort order above)
365	                // possibilities
366	                // rest1 l2 can be no smaller than l1-1; iterate to l2
367	                // rest2 test out to l1
368	                // both  test out to l1
369	                // neither = required
370	
371	
372	                if (rest2) {
373	                    // both, rest2
374	                    min = l1;
375	                } else if (rest1) {
376	                    // rest1
377	                    if (l2 < l1 - 1) return;
378	                    min = l2;
379	                } else {
380	                    // neither
381	                    if (l1 != l2) return;
382	                    min = l1;
383	                }
