423	                exclDumpln("Checking exclusion of ", pl1, " and ", pl2, ":");
424	                for (int k = 0; k < min; k++) {
425	                    FType p1 = pl1.get(k);
426	                    FType p2 = k < l2 ? pl2.get(k) : pl2.get(l2 - 1);
427	                    exclDump(k, ": ", p1, " and ", p2, ", ", p1.getExtends(), " and ", p2.getExtends(), ", ");
