429	                    p1 = deRest(p1);
430	                    p2 = deRest(p2);
431	
432	                    if (p1 == p2 && !p1.isSymbolic() && !p2.isSymbolic()) {
433	                        exclDumpln("equal.");
434	                        continue;
435	                    }
436	
437	                    /* Instances of one generic type whose static arguments may be equal: no object type for
438	                       the shortcut below, which takes two object types to exclude. */
439	                    boolean coincide = ownPair && instancesMayCoincide(p1, p2);
