463	                    boolean excludes = p1.excludesOther(p2);
464	                    /* Read each at a symbolic instantiation of its static parameters, shared where both
465	                       declare the same ones, two own generics' parameter types can exclude where instances
466	                       of each do not: the exclusion is withdrawn there. */
467	                    boolean withdrawnHere = false;
