475	                        excludes = false;
476	                    }
477	                    if (excludes) {
478	                        exclDumpln("distinct.");
479	                        distinct = true;
480	                    } else {
481	
482	                        boolean local_unrelated = true;
483	                        // Check for subtype constraint.
484	                        boolean p1subp2 = p1.subtypeOf(p2);
485	                        boolean p2subp1 = p2.subtypeOf(p1);
486	                        if (p1subp2 && !p2subp1) {
487	                            p1better = k;
488	                            local_unrelated = false;
489	                            exclDumpln(" left better.");
490	                        } else if (p2subp1 && !p1subp2) {
491	                            p2better = k;
492	                            local_unrelated = false;
493	                            exclDumpln(" right better.");
494	                        } else if (selfIndex != k) {
495	                            if (p1.isSymbolic() || withdrawnHere) sawSymbolic1 = true;
496	
497	                            if (p2.isSymbolic() || withdrawnHere) sawSymbolic2 = true;
498	                        }
499	                        if (local_unrelated && unrelated == -1) {
500	                            // Here we check for self parameters!
501	                            if (selfIndex != k) {
502	                                unrelated = k;
503	                                exclDumpln("Unrelated.");
504	                            }
505	                        }
506	                    }
507	                }
508	
509	                distinct |= unequal && (allObjInstance1 || allObjInstance2);
510	            }
511	            //      }
512	
513	            if (!distinct) {
514	                if (p1better >= 0 && p2better >= 0) {
515	                    meetOk = meetExistsIn(o1, o2, new_overloads);
516	                } else {
517	                    FType r1 = o1.getFn().getRange();
518	                    FType r2 = o2.getFn().getRange();
519	                    if (p1better >= 0) {
520	                        // subtype rule applies
521	                        result1Subtype2Failure = !r1.subtypeOf(r2);
522	                    } else if (p2better >= 0) {
523	                        // subtype rule applies
524	                        result2Subtype1Failure = !r2.subtypeOf(r1);
525	                    }
526	                }
527	            }
528	
529	
530	            if (!distinct && !overloadOk()) {
531	                DomainReading read = validOnDeclaredDomains(o1, o2, new_overloads);
532	                if (read == DomainReading.VALID) return;
533	                if (unrelated != -1 && !sawSymbolic1 && !sawSymbolic2 && overlapCovered(o1, pl1, o2, pl2, new_overloads)) return;
534	                if (read != DomainReading.NOT_READ) {
535	                    exclDumpSkip();
536	                    error(o1, o2, within, ruleFailure(read, o1, o2));
537	                }
538	            } else if (!distinct && sameDeclaredDomains(o1, o2)) {
539	                exclDumpSkip();
540	                error(o1, o2, within, ruleFailure(DomainReading.NO_DUPLICATES, o1, o2));
541	            }
542	
543	            describeOverloadingFailure(o1, o2, within, pl1, pl2);
544	
545	            return;
546	        }
