548	        public boolean overloadOk() {
549	
550	            // exclusion is good.
551	            if (distinct) return true;
552	
553	            // non-ground types need exclusion
554	            if (sawSymbolic1 || sawSymbolic2 || unrelated != -1) {
555	                return false;
556	            }
557	
558	            // meet rule
559	            if (p1better >= 0 && p2better >= 0 && !meetOk) return false;
560	
561	            // neither is better, not a functional method
562	            if (p1better < 0 && p2better < 0 && selfIndex < 0) return false;
563	
564	            if (result1Subtype2Failure || result2Subtype1Failure) return false;
565	
566	            return true;
567	        }
