751	    /**
752	     * A pair of one own generic and one declaration without static
753	     * parameters that the parameter-by-parameter check refuses, read on the
754	     * two declared domains: valid when one lies strictly inside the other and
755	     * the inner one's return type is below the outer one's for every
756	     * instance of the generic, its type parameters standing for themselves;
757	     * or when neither lies inside the other and declarations below both
758	     * cover their overlap (genericOverlapCovered).  A pair of two own
759	     * generics that the check refuses is read on the two declared domains,
760	     * each over its own instances (genericPairValid), whether or not some
761	     * pair of its parameter types excluded in the check's reading of each
762	     * at a symbolic instantiation of its static parameters.  The reading
763	     * names the rule that refuses the pair, or says that the pair is not
764	     * read on its declared domains.
765	     */
766	    static private DomainReading validOnDeclaredDomains(Overload o1, Overload o2, Collection<Overload> all) {
767	        SingleFcn f1 = o1.getFn();
768	        SingleFcn f2 = o2.getFn();
769	        if (ownGeneric(f1) && ownGeneric(f2)) return genericPairValid(o1, o2, all);
770	        Overload gen;
771	        Overload plain;
772	        if (ownGeneric(f1) && !(f2 instanceof GenericFunctionOrMethod)) {
773	            gen = o1;
774	            plain = o2;
775	        } else if (ownGeneric(f2) && !(f1 instanceof GenericFunctionOrMethod)) {
776	            gen = o2;
777	            plain = o1;
778	        } else {
779	            return DomainReading.NOT_READ;
780	        }
781	        if (hasRest(gen.getParams()) || hasRest(plain.getParams())) return DomainReading.NOT_READ;
782	        if (gen.getParams().size() != plain.getParams().size()) return DomainReading.NOT_READ;
783	        try {
784	            SingleFcn g = gen.getFn();
785	            SingleFcn p = plain.getFn();
786	            boolean plainInside = instanceHolding(g, plain.getParams(), true) != null;
787	            boolean genInside = declaredBelow(g, null, p, p, true);
788	            if (plainInside && genInside) return DomainReading.NO_DUPLICATES;
789	            if (plainInside) return p.getRange().subtypeOf(g.getRange()) ? DomainReading.VALID :
790	                                    DomainReading.returnTypeRule(plain == o1);
791	            if (genInside) return g.getRange().subtypeOf(p.getRange()) ? DomainReading.VALID :
792	                                  DomainReading.returnTypeRule(gen == o1);
793	            return genericOverlapCovered(gen, plain, all) ? DomainReading.VALID : DomainReading.MEET;
794	        }
795	        catch (FortressException ex) {
796	            return DomainReading.NOT_READ;
797	        }
798	    }
