800	    /**
801	     * A pair's reading on its declared domains (validOnDeclaredDomains): valid;
802	     * refused by one of the three rules of Specification/advanced/overloading.tex,
803	     * section "Declarations with Static Parameters" (the No Duplicates Rule,
804	     * the Return Type Rule with the first or the second of the pair the more
805	     * specific, the Meet Rule); or not read there, which leaves the
806	     * parameter-by-parameter check's refusal and its message.
807	     */
808	    enum DomainReading {
809	        VALID, NO_DUPLICATES, FIRST_RETURN_TYPE, SECOND_RETURN_TYPE, MEET, NOT_READ;
810	
811	        static DomainReading returnTypeRule(boolean firstInside) {
812	            return firstInside ? FIRST_RETURN_TYPE : SECOND_RETURN_TYPE;
813	        }
814	    }
