816	    /** The message that refuses o1 beside o2 by the rule that read names. */
817	    static private String ruleFailure(DomainReading read, Overload o1, Overload o2) {
818	        switch (read) {
819	            case NO_DUPLICATES:
820	                return errorMsg("Overloading of ", o1, " and ", o2,
821	                                " fails because their parameter lists have the same types");
822	            case FIRST_RETURN_TYPE:
823	            case SECOND_RETURN_TYPE: {
824	                boolean first = read == DomainReading.FIRST_RETURN_TYPE;
825	                return errorMsg("Overloading of ", o1, " and ", o2,
826	                                " fails the Return Type Rule: the ", first ? "first" : "second",
827	                                " is more specific, and its return type is not found to be a subtype of the",
828	                                " return type of every instance of the ", first ? "second" : "first",
829	                                " that applies to its arguments");
830	            }
831	            case MEET:
832	                return errorMsg("Overloading of ", o1, " and ", o2,
833	                                " fails the Meet Rule: neither is found to be more specific than the other",
834	                                " or to exclude it, and no declaration is found that is more specific than both",
835	                                " and applies to every call to which both apply");
836	            default:
837	                return bug("No rule refuses a pair read " + read);
838	        }
839	    }
