841	    /**
842	     * A pair that the parameter-by-parameter check passes without an
843	     * excluding parameter, of which one at least is an own generic and the
844	     * other an own generic or a declaration without static parameters, whose
845	     * declared domains, each generic's over its own instances, each lie
846	     * inside the other: the No Duplicates Rule refuses it.  The check reads
847	     * a type parameter as strictly below its bound, so it orders a generic
848	     * whose parameter types are its type parameters before one whose
849	     * parameter types are their bounds, though each is applicable to every
850	     * call to which the other is.
851	     */
852	    static private boolean sameDeclaredDomains(Overload o1, Overload o2) {
853	        SingleFcn f1 = o1.getFn();
854	        SingleFcn f2 = o2.getFn();
855	        boolean g1 = ownGeneric(f1);
856	        boolean g2 = ownGeneric(f2);
857	        if (!(g1 && g2 || g1 && !(f2 instanceof GenericFunctionOrMethod)
858	              || g2 && !(f1 instanceof GenericFunctionOrMethod))) return false;
859	        List<FType> d1 = o1.getParams();
860	        List<FType> d2 = o2.getParams();
861	        if (hasRest(d1) || hasRest(d2) || d1.size() != d2.size()) return false;
862	        try {
863	            return declaredInside(d1, f2, d2) && declaredInside(d2, f1, d1);
864	        }
865	        catch (FortressException ex) {
866	            return false;
867	        }
868	    }
