870	    /**
871	     * The types ts lie inside the declared domain d of f: some instance of f
872	     * holds them where f is an own generic, and otherwise they are a subtype
873	     * of d.
874	     */
875	    static private boolean declaredInside(List<FType> ts, SingleFcn f, List<FType> d) {
876	        if (ownGeneric(f)) return instanceHolding(f, ts, true) != null;
877	        return FTypeTuple.make(ts).subtypeOf(FTypeTuple.make(d));
878	    }
