880	    /**
881	     * Two own generics read on their declared domains, each over its own
882	     * instances: refused where each lies inside the other (the No
883	     * Duplicates Rule); valid where one lies inside the other and its return
884	     * type is below the other's at the instance that holds it, where that
885	     * instance stands for every instance of the other applicable to an
886	     * argument of the inner one (returnRuleAtEveryInstance; the Return Type
887	     * Rule); otherwise valid where a third declaration below both holds
888	     * their overlap (genericMeetCovered, the Meet Rule).  A pair that is not
889	     * valid is read as refused by the rule that it breaks.
890	     */
891	    static private DomainReading genericPairValid(Overload o1, Overload o2, Collection<Overload> all) {
892	        List<FType> d1 = o1.getParams();
893	        List<FType> d2 = o2.getParams();
894	        if (hasRest(d1) || hasRest(d2) || d1.size() != d2.size()) return DomainReading.NOT_READ;
895	        SingleFcn f = o1.getFn();
896	        SingleFcn g = o2.getFn();
897	        try {
898	            SingleFcn gHolding = instanceHolding(g, d1, true);
899	            SingleFcn fHolding = instanceHolding(f, d2, true);
900	            if (gHolding != null && fHolding != null) return DomainReading.NO_DUPLICATES;
901	            if (gHolding != null) {
902	                return f.getRange().subtypeOf(gHolding.getRange()) && returnRuleAtEveryInstance(f, d1, g, d2) ?
903	                       DomainReading.VALID : DomainReading.FIRST_RETURN_TYPE;
904	            }
905	            if (fHolding != null) {
906	                return g.getRange().subtypeOf(fHolding.getRange()) && returnRuleAtEveryInstance(g, d2, f, d1) ?
907	                       DomainReading.VALID : DomainReading.SECOND_RETURN_TYPE;
908	            }
909	            return genericMeetCovered(o1, o2, all) ? DomainReading.VALID : DomainReading.MEET;
910	        }
911	        catch (FortressException ex) {
912	            return DomainReading.NOT_READ;
913	        }
914	    }
