/**
 * Whether the existential type `ed` has no instance but Bottom: reduceED's first
 * premise, the constraint under which its body, each type parameter read as an
 * inference variable, is not equivalent to Bottom, is False, so no instantiation
 * makes it nontrivial (Section 5.3 of our paper: an intersection of types that
 * exclude has the extent of Bottom).  reduceED cannot unify False and leaves such
 * a type as it is, whose body its own type variables do not show to be Bottom.
 */
def emptyED(ed: Type): Boolean = {
  val spd = getStaticParams(ed)
  if (spd.isEmpty) return false
  val e = insertStaticParams(ta.extend(spd, None).normalize(clearStaticParams(ed)), spd)
  val sp = getStaticParams(e)
  val ia = sp.map(s => NF.make_InferenceVarType(NU.getSpan(s)))
  val vars = (ia, sp).zipped.flatMap{
    case (i, SStaticParam(info, _, n, _, _, _, _, _, _)) =>
      Some((NF.makeVarType(info.getSpan, n.asInstanceOf[Id]), i))
    case _ => None
  }
  val vi: Type => Type = liftSubstitution(Map[VarType, Type](vars.toSeq:_*))
  isFalse(negate(ta.equivalent(vi(clearStaticParams(e)), BOTTOM)))
}

